prisma_schema:
// ShopEase Prisma schema - M1 scope: catalog only (Product, ProductVariant).
// Not used at runtime in M1 (the app reads a bundled mock catalog).
// Deferred to later milestones: User, Address, Category, Cart, CartItem, Order, OrderItem, Payment.
// CHECK constraints added in the initial SQL migration:
//   price_minor >= 0, stock_quantity >= 0, currency ~ '^[A-Z]{3}$'

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model Product {
  id          String           @id @default(uuid()) @db.Uuid
  slug        String           @unique
  name        String           @db.VarChar(200)
  description String
  imageUrl    String?          @map("image_url")
  imageAlt    String           @map("image_alt") @db.VarChar(300)
  isActive    Boolean          @default(true) @map("is_active")
  createdAt   DateTime         @default(now()) @map("created_at") @db.Timestamptz(3)
  updatedAt   DateTime         @updatedAt @map("updated_at") @db.Timestamptz(3)
  variants    ProductVariant[]

  @@index([isActive, name])
  @@map("products")
}

model ProductVariant {
  id            String   @id @default(uuid()) @db.Uuid
  productId     String   @map("product_id") @db.Uuid
  sku           String   @unique @db.VarChar(64)
  size          String?  @db.VarChar(32)
  color         String?  @db.VarChar(64)
  // Price in integer minor units (cents); never a float.
  priceMinor    Int      @map("price_minor")
  // ISO 4217 currency code, e.g. USD.
  currency      String   @default("USD") @db.Char(3)
  // Stock is tracked per variant.
  stockQuantity Int      @default(0) @map("stock_quantity")
  isActive      Boolean  @default(true) @map("is_active")
  sortOrder     Int      @default(0) @map("sort_order")
  createdAt     DateTime @default(now()) @map("created_at") @db.Timestamptz(3)
  updatedAt     DateTime @updatedAt @map("updated_at") @db.Timestamptz(3)
  product       Product  @relation(fields: [productId], references: [id], onDelete: Cascade)

  @@unique([productId, size, color])
  @@index([productId, isActive])
  @@map("product_variants")
}
